Lemma cps_loop_Z : forall (I : Z -> config -> Prop) (X : config -> Prop) (N : Z),
  (forall i, 0 <= i < N -> cps asegs (I i) (fun c => (i + 1 < N /\ I (i + 1) c) \/ (i + 1 = N /\ X c))) ->
  forall i, 0 <= i < N -> cps asegs (I i) X.
